+@page "/catalog"
+@using sv_7e5ecf74a1254ff99cce68ce01ae9a6c.Models
+@using sv_7e5ecf74a1254ff99cce68ce01ae9a6c.Services
+@inject IProductService ProductService
+@rendermode InteractiveServer
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h3 class="mb-3">Product Catalog</h3>
+
+@if (_error is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @_error
+        <button class="btn btn-link p-0 ms-2" @onclick="RetryAsync">Retry</button>
+    </div>
+}
+else
+{
+    <div class="row">
+        @* ── Left Sidebar: Filters ── *@
+        <aside class="col-lg-3 mb-4">
+            <div class="card">
+                <div class="card-header fw-bold">Filters</div>
+                <div class="card-body">
+                    @* Categories *@
+                    <h6>Category</h6>
+                    @if (_categories is null)
+                    {
+                        <p class="text-muted small">Loading…</p>
+                    }
+                    else
+                    {
+                        @foreach (var cat in _categories)
+                        {
+                            <div class="form-check">
+                                <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
+                                       checked="@(_selectedCategories.Contains(cat))"
+                                       @onchange="e => ToggleCategory(cat, (bool)(e.Value ?? false))" />
+                                <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
+                            </div>
+                        }
+                    }
+
+                    <hr />
+
+                    @* Price Range *@
+                    <h6>Price Range</h6>
+                    <div class="mb-2">
+                        <label class="form-label small mb-0">Min Price</label>
+                        <input type="number" class="form-control form-control-sm"
+                               min="0" step="0.01" placeholder="0.00"
+                               @bind="_minPrice" @bind:event="oninput" />
+                    </div>
+                    <div class="mb-2">
+                        <label class="form-label small mb-0">Max Price</label>
+                        <input type="number" class="form-control form-control-sm"
+                               min="0" step="0.01" placeholder="No limit"
+                               @bind="_maxPrice" @bind:event="oninput" />
+                    </div>
+
+                    <hr />
+
+                    @* In Stock Toggle *@
+                    <div class="form-check form-switch mb-3">
+                        <input class="form-check-input" type="checkbox" id="inStockOnly"
+                               @bind="_inStockOnly" />
+                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
+                    </div>
+
+                    @* Action Buttons *@
+                    <div class="d-grid gap-2">
+                        <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync" disabled="@_loading">
+                            Apply Filters
+                        </button>
+                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync" disabled="@_loading">
+                            Clear Filters
+                        </button>
+                    </div>
+                </div>
+            </div>
+        </aside>
+
+        @* ── Main Content Area ── *@
+        <section class="col-lg-9">
+            @* Toolbar *@
+            <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
+                <div class="d-flex align-items-center gap-2">
+                    <label class="form-label mb-0 small fw-bold">Sort by:</label>
+                    <select class="form-select form-select-sm sort-select" @onchange="OnSortChangedAsync">
+                        @foreach (var opt in _sortOptions)
+                        {
+                            <option value="@opt.Value" selected="@(opt.Value == _sortBy)">@opt.Label</option>
+                        }
+                    </select>
+                </div>
+                <span class="text-muted small">
+                    @if (_result is not null && _result.Items.Count > 0)
+                    {
+                        var first = (_result.Page - 1) * _result.PageSize + 1;
+                        var last = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
+                        @($"Showing {first}–{last} of {_result.TotalCount} products")
+                    }
+                </span>
+            </div>
+
+            @* Loading State *@
+            @if (_loading)
+            {
+                <div class="text-center py-5">
+                    <div class="spinner-border text-primary" role="status">
+                        <span class="visually-hidden">Loading…</span>
+                    </div>
+                    <p class="mt-2 text-muted">Loading products…</p>
+                </div>
+            }
+            @* Empty State *@
+            else if (_result is null || _result.Items.Count == 0)
+            {
+                <div class="text-center py-5">
+                    <p class="fs-5 text-muted">No products found.</p>
+                    <p class="text-muted small">Try adjusting your filters or clearing them.</p>
+                </div>
+            }
+            @* Product Grid *@
+            else
+            {
+                <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-3 mb-4">
+                    @foreach (var product in _result.Items)
+                    {
+                        <div class="col">
+                            <ProductCard Product="product"
+                                         OnProductSelected="OnProductSelected"
+                                         OnAddToCart="OnAddToCart" />
+                        </div>
+                    }
+                </div>
+
+                @* Pagination *@
+                @if (TotalPages > 1)
+                {
+                    <nav aria-label="Product pagination">
+                        <ul class="pagination justify-content-center flex-wrap">
+                            <li class="page-item @(_currentPage <= 1 ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage - 1)"
+                                        disabled="@(_currentPage <= 1)">
+                                    Previous
+                                </button>
+                            </li>
+                            @foreach (var p in GetPageNumbers())
+                            {
+                                <li class="page-item @(p == _currentPage ? "active" : "")">
+                                    <button class="page-link" @onclick="() => GoToPageAsync(p)">@p</button>
+                                </li>
+                            }
+                            <li class="page-item @(_currentPage >= TotalPages ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage + 1)"
+                                        disabled="@(_currentPage >= TotalPages)">
+                                    Next
+                                </button>
+                            </li>
+                        </ul>
+                    </nav>
+                }
+            }
+        </section>
+    </div>
+}
+
+@code {
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    private const int PageSize = 9;
+
+    private bool _loading = true;
+    private string? _error;
+    private int _currentPage = 1;
+    private string _sortBy = "price_asc";
+    private PagedResult<Product>? _result;
+
+    // Filter state
+    private List<string>? _categories;
+    private readonly HashSet<string> _selectedCategories = new();
+    private decimal? _minPrice;
+    private decimal? _maxPrice;
+    private bool _inStockOnly;
+
+    private static readonly List<(string Label, string Value)> _sortOptions =
+    [
+        ("Price: Low to High", "price_asc"),
+        ("Price: High to Low", "price_desc"),
+        ("Name: A-Z", "name_asc"),
+        ("Rating: Highest", "rating_desc"),
+    ];
+
+    private int TotalPages => _result is null || _result.PageSize == 0
+        ? 1
+        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAsync();
+    }
+
+    private async Task LoadAsync()
+    {
+        try
+        {
+            _loading = true;
+            _error = null;
+            StateHasChanged();
+
+            var categoriesTask = _categories is null
+                ? ProductService.GetCategoriesAsync()
+                : Task.FromResult(_categories);
+
+            var searchTask = ProductService.SearchAsync(BuildFilter(), _sortBy, _currentPage, PageSize);
+
+            await Task.WhenAll(categoriesTask, searchTask);
+
+            _categories = await categoriesTask;
+            _result = await searchTask;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private ProductFilter BuildFilter() => new(
+        Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
+        MinPrice: _minPrice,
+        MaxPrice: _maxPrice,
+        InStockOnly: _inStockOnly
+    );
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            _selectedCategories.Add(category);
+        else
+            _selectedCategories.Remove(category);
+    }
+
+    private async Task ApplyFiltersAsync()
+    {
+        _currentPage = 1;
+        await LoadAsync();
+    }
+
+    private async Task ClearFiltersAsync()
+    {
+        _selectedCategories.Clear();
+        _minPrice = null;
+        _maxPrice = null;
+        _inStockOnly = false;
+        _currentPage = 1;
+        await LoadAsync();
+    }
+
+    private async Task OnSortChangedAsync(ChangeEventArgs e)
+    {
+        _sortBy = e.Value?.ToString() ?? "price_asc";
+        _currentPage = 1;
+        await LoadAsync();
+    }
+
+    private async Task GoToPageAsync(int page)
+    {
+        if (page < 1 || page > TotalPages) return;
+        _currentPage = page;
+        await LoadAsync();
+    }
+
+    private async Task RetryAsync()
+    {
+        await LoadAsync();
+    }
+
+    private Task OnAddToCart(Product product)
+    {
+        // Placeholder — integrate with cart service as needed
+        return Task.CompletedTask;
+    }
+
+    private IEnumerable<int> GetPageNumbers()
+    {
+        const int maxVisible = 5;
+        int total = TotalPages;
+        int start = Math.Max(1, _currentPage - maxVisible / 2);
+        int end = Math.Min(total, start + maxVisible - 1);
+        start = Math.Max(1, end - maxVisible + 1);
+
+        for (int i = start; i <= end; i++)
+            yield return i;
+    }
+}
